package cli

import (
	"fmt"

	"github.com/spf13/cobra"

	"github.com/mvanhorn/printing-press-library/library/devices/averusa/internal/averusa"
	"github.com/mvanhorn/printing-press-library/library/devices/averusa/internal/cliutil"
)

func newProductsListCmd(flags *rootFlags) *cobra.Command {
	var dbPath string
	var category string
	var limit int

	cmd := &cobra.Command{
		Use:         "list",
		Short:       "List the product catalog, optionally filtered by category",
		Example:     "  averusa-pp-cli products list --category conference-camera",
		Annotations: map[string]string{"pp:method": "GET", "pp:path": "https://www.averusa.com/sitemap.xml", "mcp:read-only": "true"},
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) == 0 && cmd.Flags().NFlag() == 0 {
				return cmd.Help()
			}
			if dryRunOK(flags) {
				return writeDryRun(cmd.OutOrStdout(), flags, "products list")
			}
			// Store-backed path: serve from the corpus. A filtered query with
			// no matches returns the honest empty result (never a fall-through
			// to unrelated live data); --data-source local must never touch
			// the network. Only --data-source auto with NO filter flags falls
			// through to the live sitemap when the corpus is empty.
			if flags.dataSource != "live" {
				dbPath = corpusDBPath(dbPath)
				corpusPresent := !corpusMissing(cmd, flags, dbPath)
				if corpusPresent {
					ctx, cancel := boundCtx(cmd.Context(), flags)
					defer cancel()
					st, err := openCorpus(ctx, dbPath)
					if err != nil {
						return err
					}
					defer st.Close()
					if limit <= 0 {
						limit = 200
					}
					prods, err := st.ListAVERUSAProducts(category, limit)
					if err != nil {
						return err
					}
					if len(prods) > 0 || category != "" || flags.dataSource == "local" {
						// Non-empty, or an explicitly filtered / local-only
						// query: empty is the correct answer, not live data.
						if len(prods) == 0 {
							fmt.Fprintf(cmd.ErrOrStderr(), "no products%s in the corpus; run `averusa-pp-cli harvest --only products` first\n",
								map[bool]string{true: " for category " + category, false: ""}[category != ""])
						}
						if flags.asJSON {
							return flags.printJSON(cmd, prods)
						}
						w := cmd.OutOrStdout()
						for _, p := range prods {
							mark := " "
							if p.Discontinued {
								mark = "x"
							}
							fmt.Fprintf(w, "%s %-14s %-24s %s\n", mark, p.Slug, p.Category, p.Name)
						}
						return nil
					}
					// Empty corpus, unfiltered auto: fall through to live.
				} else if flags.dataSource == "local" {
					// Local mode with no corpus: no network, honest empty.
					if flags.asJSON {
						return flags.printJSON(cmd, []any{})
					}
					fmt.Fprintln(cmd.ErrOrStderr(), "no products in the corpus; run `averusa-pp-cli harvest --only products` first")
					return nil
				}
			}

			// Fallback: fetch + parse the live sitemap (no corpus yet).
			if cliutil.IsVerifyEnv() {
				fmt.Fprintln(cmd.OutOrStdout(), "would fetch the averusa.com product sitemap")
				return nil
			}
			ctxL, cancelL := boundCtx(cmd.Context(), flags)
			defer cancelL()
			c := averusa.New()
			refs, err := c.ProductRefs(ctxL)
			if err != nil {
				return classifyAPIError(err, flags)
			}
			if limit > 0 && limit < len(refs) {
				refs = refs[:limit]
			}
			entries := make([]map[string]any, 0, len(refs))
			for _, r := range refs {
				entries = append(entries, map[string]any{
					"slug":          r.Slug,
					"category":      r.Category,
					"name":          "",
					"url":           r.URL,
					"datasheet_url": "",
					"discontinued":  false,
				})
			}
			if flags.asJSON {
				return flags.printJSON(cmd, entries)
			}
			w := cmd.OutOrStdout()
			for _, e := range entries {
				fmt.Fprintf(w, "%-14s %s\n", e["category"], e["slug"])
			}
			return nil
		},
	}
	cmd.Flags().StringVar(&dbPath, "db", "", "corpus database path (default: CLI state dir)")
	cmd.Flags().StringVar(&category, "category", "", "category filter, e.g. conference-camera, ptz-camera, document-camera")
	cmd.Flags().IntVar(&limit, "limit", 0, "max results (default 200)")
	return cmd
}
